mapper.select:
select g.id, g.member_id as memberId, coalesce((select max(c.level) from growth_level_config c where c.need_exp is not null and c.need_exp <= g.exp_value), 1) as levelNo, g.exp_value as expValue, g.last_active_time as lastActiveTime, g.create_time as createTime, g.update_time as updateTime from member_growth g
and g.member_id = #{memberId}
order by g.update_time desc, g.id desc

mapper.update:
update member_growth
set exp_value = exp_value + #{expValue},
    last_active_time = #{lastActiveTime},
    update_time = #{updateTime}
where member_id = #{memberId}

update member_exp_earned set revoked_exp = revoked_exp + #{exp}
where member_id = #{memberId} and mission_progress_id = #{missionProgressId}
  and exp_value - revoked_exp >= #{exp}

update member_exp_earned set revoked_exp = revoked_exp + #{exp}
where id = #{earnedExpId} and member_id = #{memberId}
  and exp_value - revoked_exp >= #{exp}

update member_growth
set exp_value = exp_value - #{exp}, update_time = now()
where member_id = #{memberId} and exp_value >= #{exp}
